  type: "tree";
  /**
   * The kinds of row the tree can hold, keyed by type name.
   * Each entry declares \`allowedChildTypes\` \u2014 which is what makes the tree a tree rather than a list \u2014 plus optional \`icon\`, \`color\`, \`label\`, \`labelField\` (which record field titles the row) and \`detail\` (a child node rendered as that type's detail view).
   */
  nodeTypes: Record<string, TreeNodeOptions>;
